AyaSurahInfo? getAyaSurah(int n) {
  if (n < 1 || n > 114) return null;
  return kAyaSurahs[n - 1];
}

/// Calculate exact page count for an aya range (single-surah only).
/// Mirror of the backend's calculatePages algorithm.
double calculateLocalPages(int surah, int startAya, int endAya) {
  final s = getAyaSurah(surah);
  if (s == null) return 0;
  if (startAya < 1 || endAya > s.numAyas || endAya < startAya) return 0;

  // Pages our range touches → how many of our ayas are on each page
  final ourAyasPerPage = <int, int>{};
  for (var a = startAya; a <= endAya; a++) {
    final page = s.ayaPages[a - 1];
    ourAyasPerPage[page] = (ourAyasPerPage[page] ?? 0) + 1;
  }

  // Total ayas on each touched page (across ALL surahs)
  final totalAyasPerPage = <int, int>{};
  for (final p in ourAyasPerPage.keys) {
    totalAyasPerPage[p] = 0;
  }
  for (final other in kAyaSurahs) {
    for (final p in other.ayaPages) {
      if (totalAyasPerPage.containsKey(p)) {
        totalAyasPerPage[p] = (totalAyasPerPage[p] ?? 0) + 1;
      }
    }
  }

  double total = 0;
  ourAyasPerPage.forEach((page, ours) {
    final tot = totalAyasPerPage[page] ?? ours;
    if (tot > 0) total += ours / tot;
  });

  return double.parse((total).toStringAsFixed(3));
}
